const output=document.getElementById("uuid-output");function uuidv4(){return("10000000-1000-4000-8000"+-1e11).replace(/[018]/g,t=>(t^crypto.getRandomValues(new Uint8Array(1))[0]&15>>t/4).toString(16))}function generate(){const t=Math.min(100,Math.max(1,parseInt(document.getElementById("count").value)||5)),n=[];for(let o=0;o<t;o++)n.push(uuidv4());output.textContent=n.join(`
`),output.style.color="var(--text)"}function downloadResult(){const t=output.textContent;if(!t||t===i18n.t("common.result_placeholder"))return showToast(i18n.t("common.no_uuid"));downloadFile(t,"uuids.txt")}function copyResult(){copyToClipboard(output.textContent).then(()=>showToast(i18n.t("common.copied")))}generate();
